(1751, 418, '4e27e0f16e3e8fe79997f92f356eb0e3', NULL, '2.8.5', NULL, NULL, NULL, NULL, NULL, '2.8.5 Programa de Gerenciamento de Resíduos Sólidos e Efluentes Líquidos', NULL, '2024-04-11 15:06:05', '2024-04-11 15:06:05', NULL),
(1752, 418, 'd9b9d51057757f2f69117c352627edd0', NULL, '2.8.6', NULL, NULL, NULL, NULL, NULL, '2.8.6 Programa de Monitoramento e Controle de Material Particulado, Fumaça Preta e Ruídos', NULL, '2024-04-11 15:06:20', '2024-04-11 15:06:20', NULL),
(1753, 418, 'fddad33d1192fa45fdffecaf2816be13', NULL, '2.8.7', NULL, NULL, NULL, NULL, NULL, '2.8.7 Programa de Monitoramento da Qualidade da Água', NULL, '2024-04-11 15:06:33', '2024-04-11 15:06:33', NULL),
(1754, 418, 'c80aceae93b005f02210bec89f4a52a0', NULL, '2.8.8', NULL, NULL, NULL, NULL, NULL, '2.8.8 Programa de Paralisação e Desmobilização de Obras', NULL, '2024-04-11 15:06:48', '2024-04-11 15:06:48', NULL),
(1755, 418, '6cefe121e7d3bc16398eda00ad115c39', NULL, '2.8.9', NULL, NULL, NULL, NULL, NULL, '2.8.9 Plano de Redução de Acidentes e Desconforto durante a Fase de Obras', NULL, '2024-04-11 15:06:59', '2024-04-11 15:06:59', NULL),
(1756, 418, '11cf8181e8851241552631dcb5470e84', NULL, '2.8.10', NULL, NULL, NULL, NULL, NULL, '2.8.10 Plano de Gerenciamento de Riscos (PGR) e Plano de Ação de Emergências (PAE)', NULL, '2024-04-11 15:07:11', '2024-04-11 15:07:11', NULL),
