(4, '4a97840b23b2b4a8cac9450565d4854f', 1, 'null', 'Drone - DJI Air 3', 'null', 'null', 'O DJI Air 3 conta com sistemas otimizados de câmera, transmissão de vídeos e de detecção visual, além de tempo de voo prolongado e recursos inteligentes.', 'null', 'Monitoramento de atropelamento de fauna', 'O tempo máximo de voo estacionário é de 42 minutos, e o tempo máximo de voo é de 46 minutos. O drone suporta Voo com Trajetória, RTH avançado, Piloto automático, QuickTransfer e outras funções inteligentes.', 'null', 'null', NULL, '2023-08-09 18:00:54', '2023-08-09 19:34:44', NULL),
(5, '1a72f7413178bf6808c23bb98a9c02ed', 1, 'null', 'Sonda Multiparamétrica', 'null', 'null', 'Sonda de análise de água em campo', 'null', 'Programa de Monitoramento da qualidade da água', 'Sonda para análise de condutividade elétrica; oxigênio dissolvido; pH; salinidade; ', 'null', 'null', NULL, '2023-09-20 13:21:08', '2023-09-20 13:21:23', NULL),
